}

function OrderingFront() {
  return (
    <main>
      <h1>校園點餐系統</h1>
      <nav aria-label="登入">
        <ul>
          <li><a href="/student/sign-in">學生登入</a></li>
          <li><a href="/merchant/sign-in">商家後台登入</a></li>
          <li><a href="/administration/sign-in">後台管理系統登入</a></li>
        </ul>
      </nav>
      <section aria-labelledby="merchants">
        <h2 id="merchants">商家</h2>
