const screens = new Map<string, ReactNode>([
  ['/', <OrderingFront />],
  ['/student/sign-in', <StudentSignIn />],
  ['/student/register', <StudentRegistration />],
  ['/merchant/sign-in', <MerchantSignIn />],
  ['/administration/sign-in', <AdministratorSignIn />],
